changeSet.sql:
ALTER TABLE kabipay_ops.organization_command_intent
 ADD COLUMN identity_version BIGINT CHECK(identity_version IS NULL OR identity_version>0),
 ADD COLUMN source_link_version BIGINT CHECK(source_link_version IS NULL OR source_link_version>0),
 ADD CONSTRAINT organization_command_intent_identity_epochs CHECK((identity_version IS NULL)=(source_link_version IS NULL));
-- Older intents deliberately have unknown epochs. They predate durable source
-- jobs and cannot acquire a new job execution authorization through a backfill.
ALTER TABLE kabipay_ops.organization_command_intent DROP CONSTRAINT organization_command_intent_status_check;
ALTER TABLE kabipay_ops.organization_command_intent ADD CONSTRAINT organization_command_intent_status_check
 CHECK(status IN ('SUBMITTED','ACCEPTED','COMMITTED','AWAITING_CONFIRMATION','REJECTED','CANCELLED_NOT_EXECUTED'));

rollback.sql:
DO $guard$ BEGIN
 IF EXISTS(SELECT 1 FROM kabipay_ops.organization_command_intent WHERE status='ACCEPTED') THEN
  RAISE EXCEPTION 'Retain durable job acceptance and reconcile jobs before rollback';
 END IF;
END $guard$;
ALTER TABLE kabipay_ops.organization_command_intent DROP CONSTRAINT organization_command_intent_status_check;
ALTER TABLE kabipay_ops.organization_command_intent ADD CONSTRAINT organization_command_intent_status_check
 CHECK(status IN ('SUBMITTED','COMMITTED','AWAITING_CONFIRMATION','REJECTED','CANCELLED_NOT_EXECUTED'));
ALTER TABLE kabipay_ops.organization_command_intent DROP CONSTRAINT organization_command_intent_identity_epochs;
ALTER TABLE kabipay_ops.organization_command_intent DROP COLUMN identity_version, DROP COLUMN source_link_version;
